    private function do_subscribe_public(string $name, string $symbol, string $messageHash, $params = array()) {
        /**
         * @ignore
         * subscribes to a public channel of one $market
         * @param {string} $name the channel $name
         * @param {string} $symbol unified $market $symbol
         * @param {string} $messageHash the message hash the subscription resolves
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the resolved value of the subscription
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $url = $this->urls['api']['ws'];
        $request = array(
            'event' => 'subscribe',
            'symbol' => $market['id'],
            'subscription' => array(
                'name' => $name,
            ),
        );
        return Async\await($this->watch($url, $messageHash, $this->extend($request, $params), $messageHash));
    }

