    public function parse_ws_trade(array $trade, ?array $market = null): array {
        //
        // public-trades
        //
        //     {
        //         "side": "buy",
        //         "price": 73797.26,
        //         "amount": 0.0015,
        //         "timestamp": 1794378421725
        //     }
        //
        // my-trades
        //
        //     {
        //         "id": "9adb20ae-f673-49a4-b232-75442e3af617",
        //         "userId": "7bd4cc22-7682-4e45-85b3-29386b979d75",
        //         "timestamp": 1665997927993,
        //         "datetime": "2022-10-17T09:12:07.993Z",
        //         "symbol": "B2M/EUR",
        //         "order": "69d3df53-9248-430c-9850-d72ff1f0befa",
        //         "side": "sell",
        //         "price": 0.014,
        //         "amount": 100,
        //         "cost": 1.4,
        //         "fee": { "cost": 0.00224, "currency": "EUR", "rate": 0.16 },
        //         "isMaker": true,
        //         "clientOrderId": "MY-CLIENT-ORDER-ID"
        //     }
        //
        $marketId = $this->safe_string($trade, 'symbol');
        $resolvedMarket = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($trade, 'timestamp');
        $isMaker = $this->safe_bool($trade, 'isMaker');
        $takerOrMaker = null;
        if ($isMaker !== null) {
            $takerOrMaker = ($isMaker) ? 'maker' : 'taker';
        }
        $fee = null;
        $rawFee = $this->safe_dict($trade, 'fee');
        if ($rawFee !== null) {
            $feeRate = null;
            $feePercentage = $this->safe_string($rawFee, 'rate');
            if ($feePercentage !== null) {
                $feeRate = Precise::string_div($feePercentage, '100');
            }
            $fee = array(
                'cost' => $this->safe_string($rawFee, 'cost'),
                'currency' => $this->safe_currency_code($this->safe_string($rawFee, 'currency')),
                'rate' => $feeRate,
            );
        }
        return $this->safe_trade(array(
            'info' => $trade,
            'id' => $this->safe_string($trade, 'id'),
            'symbol' => $resolvedMarket['symbol'],
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'order' => $this->safe_string($trade, 'order'),
            'type' => null,
            'side' => $this->safe_string_lower($trade, 'side'),
            'takerOrMaker' => $takerOrMaker,
            'price' => $this->safe_string($trade, 'price'),
            'amount' => $this->safe_string($trade, 'amount'),
            'cost' => $this->safe_string($trade, 'cost'),
            'fee' => $fee,
        ), $resolvedMarket);
    }

