    public function parse_ws_order(array $order, ?array $market = null): array {
        //
        //     {
        //         "id": "51002851-2f76-4c10-9b4c-bcc131f27b1d",
        //         "userId": "7bd4cc22-7682-4e45-85b3-29386b979d75",
        //         "timestamp": 1666006194005,
        //         "datetime": "2022-10-17T11:29:54.005Z",
        //         "side": "buy",
        //         "symbol": "B2M/EUR",
        //         "price": 1,
        //         "stopPrice": 0,
        //         "amount": 1000,
        //         "filled": 10,
        //         "remainingAmount": 990,
        //         "dustAmount": 0,
        //         "status": "cancelled",
        //         "type": "limit",
        //         "cost": 0,
        //         "clientOrderId": "MY-CLIENT-ORDER-ID",
        //         "timeInForce": "GTC",
        //         "cancelationReason": "CR-1: User request",
        //         "feeAmount": 23.324123,
        //         "feeCurrency": "B2M"
        //     }
        //
        $marketId = $this->safe_string($order, 'symbol');
        $resolvedMarket = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($order, 'timestamp');
        $fee = null;
        $feeCost = $this->safe_number($order, 'feeAmount');
        if ($feeCost !== null) {
            $fee = array(
                'cost' => $feeCost,
                'currency' => $this->safe_currency_code($this->safe_string($order, 'feeCurrency')),
            );
        }
        return $this->safe_order(array(
            'info' => $order,
            'id' => $this->safe_string($order, 'id'),
            'clientOrderId' => $this->safe_string($order, 'clientOrderId'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => null,
            'lastUpdateTimestamp' => null,
            'symbol' => $resolvedMarket['symbol'],
            'type' => $this->parseOrderType($this->safe_string($order, 'type')),
            'timeInForce' => $this->safe_string($order, 'timeInForce'),
            'postOnly' => null,
            'reduceOnly' => null,
            'side' => $this->safe_string_lower($order, 'side'),
            'price' => $this->omit_zero($this->safe_string($order, 'price')),
            'triggerPrice' => $this->omit_zero($this->safe_string($order, 'stopPrice')),
            'amount' => $this->safe_string($order, 'amount'),
            'cost' => $this->safe_string($order, 'cost'),
            'average' => null,
            'filled' => $this->safe_string($order, 'filled'),
            'remaining' => $this->safe_string($order, 'remainingAmount'),
            'status' => $this->parse_order_status($this->safe_string($order, 'status')),
            'fee' => $fee,
            'trades' => null,
        ), $resolvedMarket);
    }

