    }

    private function do_create_order_ws(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()) {
        /**
         * create a trade order over the websocket
         *
         * @see https://api.bit2me.com/docs/pro/websocket-commands
         *
         * @param {string} $symbol unified $symbol of the $market to create an order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much you want to trade in units of the base currency
         * @param {float} [$price] the $price at which the order is to be fulfilled, in units of the quote currency, required for limit orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint, the same as for createOrder
         * @param {float} [$params->triggerPrice] the $price at which a stop-limit order is activated, requires a limit $price
         * @param {float} [$params->cost] for $market orders only, the $amount to trade in units of the quote currency, overrides $amount
         * @param {string} [$params->clientOrderId] a unique identifier for the order
         * @return {array} an [order structure](https://docs.ccxt.com/#/?id=order-structure)
         */
        Async\await($this->load_markets());
        Async\await($this->authenticate());
        $market = $this->market($symbol);
        $restRequest = $this->create_order_request($symbol, $type, $side, $amount, $price, $params);
        $orderType = $this->safe_string($restRequest, 'orderType');
        if ($orderType === 'oco') {
            throw new NotSupported($this->id . ' createOrderWs() does not support oco orders, use createOrder() instead');
        }
        // createOrderRequest always sets a CCXT-<id> clientOrderId, the response is matched by it
        $clientOrderId = $this->safe_string($restRequest, 'clientOrderId');
        $request = $this->omit($restRequest, 'orderType');
        $request['event'] = 'add-order';
        $request['type'] = $orderType;
        $request['clientOrderId'] = $clientOrderId;
        // the response carries no request id, it is matched by the client order id, and an error only by the symbol
        $pending = $this->safe_dict($this->options, 'pendingWsOrders', array());
        $pending[$clientOrderId] = $market['id'];
        $this->options['pendingWsOrders'] = $pending;
        $url = $this->urls['api']['ws'];
        $messageHash = 'added-order:' . $clientOrderId;
        return Async\await($this->watch($url, $messageHash, $request, $messageHash));
    }

    public function settle_request(Client $client, string $messageHash, mixed $result, mixed $error = null) {
        /**
         * @ignore
         * resolves or rejects a one-shot command and forgets its subscription so the same command can be sent again
         * @param {array} $client the websocket $client
         * @param {string} $messageHash the message hash of the command
         * @param {array} $result the value to resolve with
         * @param {array} [$error] when set the command is rejected with it instead
         */
        if (is_array($client->subscriptions) && array_key_exists($messageHash ?? '', $client->subscriptions)) {
            unset($client->subscriptions[$messageHash]);
        }
        if ($error !== null) {
            $client->reject($error, $messageHash);
        } else {
            $client->resolve($result, $messageHash);
        }
    }

    public function handle_create_order(Client $client, array $message) {
        //
        //     {
        //         "event": "added-order",
        //         "symbol": "BTC/USDC",
        //         "data": {
        //             "id": "f0f895d1-f9e0-494c-87b4-40e12ce344a1",
        //             "userId": "7bd4cc22-7682-4e45-85b3-29386b979d75",
        //             "side": "buy",
        //             "symbol": "BTC/USDC",
        //             "status": "open",
        //             "orderType": "limit",
        //             "createdAt": "2026-11-11T06:27:02.617Z",
        //             "updatedAt": "2026-11-11T06:27:02.617Z",
        //             "clientOrderId": "c4022a5f-cfb3-46ff-9136-2739e34dd4e6",
        //             "cancelReason": null,
        //             "timeInForce": "GTC",
        //             "feeCurrency": null,
        //             "price": 36000,
        //             "orderAmount": 0.0001,
        //             "filledAmount": 0,
        //             "cost": 0,
        //             "stopPrice": 0,
        //             "feeAmount": 0,
        //             "orderGroupId": null
        //         }
        //     }
        //
        $data = $this->safe_dict($message, 'data', array());
        $order = $this->parse_order($data);
        $clientOrderId = $this->safe_string($data, 'clientOrderId');
        if ($clientOrderId !== null) {
            $pending = $this->safe_dict($this->options, 'pendingWsOrders', array());
            $this->options['pendingWsOrders'] = $this->omit($pending, $clientOrderId);
            $this->settle_request($client, 'added-order:' . $clientOrderId, $order);
        }
    }

    public function cancel_order_ws(string $id, ?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_order_ws(...))($id, $symbol, $params);
    }

    private function do_cancel_order_ws(string $id, ?string $symbol = null, $params = array()) {
        /**
         * cancels an open order over the websocket
         *
         * @see https://api.bit2me.com/docs/pro/websocket-commands
         *
         * @param {string} $id order $id
         * @param {string} [$symbol] not used by bit2me.cancelOrderWs
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an [order structure](https://docs.ccxt.com/#/?$id=order-structure)
         */
        Async\await($this->load_markets());
        Async\await($this->authenticate());
        $request = array(
            'event' => 'cancel-order',
            'orderId' => $id,
        );
        $url = $this->urls['api']['ws'];
        $messageHash = 'canceled-order:' . $id;
        return Async\await($this->watch($url, $messageHash, $this->extend($request, $params), $messageHash));
    }

    public function handle_cancel_order(Client $client, array $message) {
        //
        //     {
        //         "event": "canceled-order",
        //         "symbol": "BTC/USDC",
        //         "data": {
        //             "orderId": "f0f895d1-f9e0-494c-87b4-40e12ce344a1",
        //             "status": "cancelled"
        //         }
        //     }
        //
        $data = $this->safe_dict($message, 'data', array());
        $orderId = $this->safe_string($data, 'orderId');
        $marketId = $this->safe_string($message, 'symbol');
        $market = $this->safe_market($marketId);
        $order = $this->safe_order(array(
            'info' => $message,
            'id' => $orderId,
            'symbol' => $market['symbol'],
            'status' => $this->parse_order_status($this->safe_string($data, 'status')),
        ), $market);
        $this->settle_request($client, 'canceled-order:' . $this->safe_string($data, 'orderId', ''), $order);
    }

    public function cancel_orders_ws(array $ids, ?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_orders_ws(...))($ids, $symbol, $params);
    }

    private function do_cancel_orders_ws(array $ids, ?string $symbol = null, $params = array()) {
        /**
         * cancels multiple orders over the websocket, up to 20 at a time
         *
         * @see https://api.bit2me.com/docs/pro/websocket-commands
         *
         * @param {string[]} $ids order $ids
         * @param {string} [$symbol] not used by bit2me.cancelOrdersWs
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [order structures](https://docs.ccxt.com/#/?id=order-structure), orders the exchange refused to cancel keep an null status and carry the reason in info
         */
        Async\await($this->load_markets());
        Async\await($this->authenticate());
        $request = array(
            'event' => 'cancel-orders',
            'ordersId' => $ids,
        );
        $url = $this->urls['api']['ws'];
        $messageHash = 'canceled-orders';
        return Async\await($this->watch($url, $messageHash, $this->extend($request, $params), $messageHash));
    }

    public function handle_cancel_orders(Client $client, array $message) {
        //
        //     {
        //         "event": "canceled-orders",
        //         "data": {
        //             "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96",
        //             "ordersDeleted": [
        //                 { "id": "cab25117-47ce-4991-98d3-3a334afbc6a0", "status": "cancelled" }
        //             ],
        //             "ordersNotDeletedReasons": [
        //                 {
        //                     "id": "a00ea616-aed4-44eb-9e05-b55c475e39d9",
        //                     "reason": "The order with ID a00ea616-aed4-44eb-9e05-b55c475e39d9 was not found",
        //                     "error": { "code": "ORDER_NOT_FOUND", "message": "The order with ID a00ea616-aed4-44eb-9e05-b55c475e39d9 was not found" }
        //                 }
        //             ]
        //         }
        //     }
        //
        $data = $this->safe_dict($message, 'data', array());
        $deleted = $this->safe_list($data, 'ordersDeleted', array());
        $notDeleted = $this->safe_list($data, 'ordersNotDeletedReasons', array());
        $orders = array();
        for ($i = 0; $i < count($deleted); $i++) {
            $entry = $deleted[$i];
            $orders[] = $this->safe_order(array(
                'info' => $entry,
                'id' => $this->safe_string($entry, 'id'),
                'status' => $this->parse_order_status($this->safe_string($entry, 'status')),
            ));
        }
        for ($i = 0; $i < count($notDeleted); $i++) {
            $entry = $notDeleted[$i];
            $orders[] = $this->safe_order(array(
                'info' => $entry,
                'id' => $this->safe_string($entry, 'id'),
                'status' => null,
            ));
        }
        $this->settle_request($client, 'canceled-orders', $orders);
    }

    public function cancel_all_orders_ws(?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_all_orders_ws(...))($symbol, $params);
    }

    private function do_cancel_all_orders_ws(?string $symbol = null, $params = array()) {
        /**
         * cancels all open orders of a $market over the websocket
         *
         * @see https://api.bit2me.com/docs/pro/websocket-commands
         *
         * @param {string} $symbol unified $market $symbol of the $market to cancel orders in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->side] 'buy' or 'sell', to cancel only that side
         * @return {array[]} a list of [order structures](https://docs.ccxt.com/#/?id=order-structure)
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' cancelAllOrdersWs() requires a symbol argument');
        }
        Async\await($this->load_markets());
        Async\await($this->authenticate());
        $market = $this->market($symbol);
        $request = array(
            'event' => 'cancel-all-orders',
            'symbol' => $market['id'],
        );
        $url = $this->urls['api']['ws'];
        $messageHash = 'canceled-all-orders:' . $this->safe_string($market, 'id', '');
        return Async\await($this->watch($url, $messageHash, $this->extend($request, $params), $messageHash));
    }

    public function handle_cancel_all_orders(Client $client, array $message) {
        //
        //     {
        //         "event": "canceled-all-orders",
        //         "symbol": "BTC/USDC",
        //         "data": {
        //             "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96",
        //             "cancelledOrders": [ "c5dfb28b-a306-4682-acdd-1271a299ca6b" ]
        //         }
        //     }
        //
        $marketId = $this->safe_string($message, 'symbol');
        $market = $this->safe_market($marketId);
        $data = $this->safe_dict($message, 'data', array());
        $ids = $this->safe_list($data, 'cancelledOrders', array());
        $orders = array();
        for ($i = 0; $i < count($ids); $i++) {
            $orders[] = $this->safe_order(array(
                'info' => $message,
                'id' => $this->safe_string($ids, $i),
                'symbol' => $this->safe_string($market, 'symbol'),
                'status' => 'canceled',
            ), $market);
        }
        $this->settle_request($client, 'canceled-all-orders:' . $this->safe_string($message, 'symbol', ''), $orders);
    }

    public function authenticate($params = array()) {
        return Async\async(self::do_authenticate(...))($params);
    }

    private function do_authenticate($params = array()) {
        /**
         * @ignore
         * authenticates the websocket connection with a short-lived token obtained over REST
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the authentication message
         */
        $url = $this->urls['api']['ws'];
        $client = $this->client($url);
        $messageHash = 'authenticated';
        $future = $client->reusableFuture($messageHash);
        $authenticated = $this->safe_value($client->subscriptions, $messageHash);
        if ($authenticated === null) {
            // the token is valid for one minute, it is only used to open the session
            $response = Async\await($this->privatePostV1SigninApikey($params));
            //
            //     { "accessToken": { "token": "header.payload.signature", "expirationTime": 1794378427 } }
            //
            $accessToken = $this->safe_dict($response, 'accessToken', array());
            $request = array(
                'event' => 'authenticate',
                'token' => $this->safe_string($accessToken, 'token'),
            );
            $this->watch($url, $messageHash, $request, $messageHash);
        }
        return Async\await($future);
    }

    public function handle_authenticate(Client $client, array $message) {
        //
        //     { "event": "authenticate" }
        //     { "event": "authenticate", "error": "jwt expired" }
        //
        $messageHash = 'authenticated';
        $error = $this->safe_string($message, 'error');
        if ($error === null) {
            // the future is reusable, every later authenticate() call awaits the same resolved value
            $future = $this->safe_value($client->futures, $messageHash);
            $future->resolve($message);
        } else {
            $exception = new AuthenticationError($this->id . ' ' . $this->json($message));
            $client->reject($exception, $messageHash);
            if (is_array($client->subscriptions) && array_key_exists($messageHash ?? '', $client->subscriptions)) {
                unset($client->subscriptions[$messageHash]);
            }
        }
    }

    public function handle_subscription_status(Client $client, array $message) {
        //
        //     { "event": "subscribe", "symbol": "BTC/USDC", "subscription": { "name": "order-book" }, "result": "subscribed" }
        //     { "event": "unsubscribe" }
        //
        return $message;
    }

    public function handle_error_message(Client $client, array $message) {
        //
        //     { "event": "added-order", "symbol": "BTC/USDC", "error": { "code": "PRICE_LOWER_MARKET_MIN", "minPrice": 0.001, "message": "The price can not be lower than 0.001" } }
        //     { "event": "canceled-order", "orderId": "73352609-a885-4dc6-99c4-8a03e5df6bda", "error": { "code": "ORDER_NOT_FOUND", "message": "The order with ID 73352609-a885-4dc6-99c4-8a03e5df6bda was not found" } }
        //
        $event = $this->safe_string($message, 'event');
        $error = $this->safe_dict($message, 'error', array());
        $code = $this->safe_string($error, 'code');
        $errorMessage = $this->safe_string($error, 'message');
        $feedback = $this->id . ' ' . $this->json($message);
        $exception = null;
        try {
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $code, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $errorMessage, $feedback);
            $exception = new ExchangeError($feedback);
        } catch (Exception $e) {
            $exception = $e;
        }
        if ($event === 'added-order') {
            // the error carries no client order id, reject every order of the symbol still waiting for a response
            $marketId = $this->safe_string($message, 'symbol');
            $pending = $this->safe_dict($this->options, 'pendingWsOrders', array());
            $clientOrderIds = is_array($pending) ? array_keys($pending) : array();
            for ($i = 0; $i < count($clientOrderIds); $i++) {
                $clientOrderId = $clientOrderIds[$i];
                $pendingMarketId = $this->safe_string($pending, $clientOrderId);
                if ($pendingMarketId === $marketId) {
                    $this->settle_request($client, 'added-order:' . $clientOrderId, null, $exception);
                    $this->options['pendingWsOrders'] = $this->omit($this->options['pendingWsOrders'], $clientOrderId);
                }
            }
        } elseif ($event === 'canceled-order') {
            $this->settle_request($client, 'canceled-order:' . $this->safe_string($message, 'orderId', ''), null, $exception);
        } elseif ($event === 'canceled-orders') {
            $this->settle_request($client, 'canceled-orders', null, $exception);
        } elseif ($event === 'canceled-all-orders') {
            $this->settle_request($client, 'canceled-all-orders:' . $this->safe_string($message, 'symbol', ''), null, $exception);
        } elseif ($event === 'subscribe') {
            // a refused subscription names the channel and the symbol it was asked for
            $subscription = $this->safe_dict($message, 'subscription', array());
            $name = $this->safe_string($subscription, 'name');
            $marketId = $this->safe_string($message, 'symbol');
            $symbol = $this->safe_symbol($marketId);
            $hashes = array(
                'order-book' => 'orderbook:' . $symbol,
                'public-trades' => 'trades:' . $symbol,
                'my-orders' => 'orders',
                'my-trades' => 'myTrades',
                'my-balance' => 'balance',
            );
            $messageHash = $this->safe_string($hashes, $name);
            if ($messageHash !== null) {
                $client->reject($exception, $messageHash);
                if (($name === 'my-orders') || ($name === 'my-trades')) {
                    // the private channels are account-wide, a symbol-scoped watchOrders / watchMyTrades waits on orders:SYMBOL / myTrades:SYMBOL
                    $scopedPrefix = $messageHash . ':';
                    $pendingHashes = is_array($client->futures) ? array_keys($client->futures) : array();
                    for ($i = 0; $i < count($pendingHashes); $i++) {
                        $pendingHash = $pendingHashes[$i];
                        if (str_starts_with($pendingHash, $scopedPrefix)) {
                            $client->reject($exception, $pendingHash);
                        }
                    }
                }
                if (($name !== null) && (is_array($client->subscriptions) && array_key_exists($name ?? '', $client->subscriptions))) {
                    unset($client->subscriptions[$name]);
                }
                if (is_array($client->subscriptions) && array_key_exists($messageHash ?? '', $client->subscriptions)) {
                    unset($client->subscriptions[$messageHash]);
                }
            }
        }
    }

    public function handle_message(Client $client, array $message) {
        $event = $this->safe_string($message, 'event');
        if ($event === 'authenticate') {
            $this->handle_authenticate($client, $message);
            return;
        }
        $error = $this->safe_value($message, 'error');
        if ($error !== null) {
            $this->handle_error_message($client, $message);
            return;
        }
        $methods = array(
            'order-book' => array($this, 'handle_order_book'),
            'public-trades' => array($this, 'handle_trades'),
            'my-orders' => array($this, 'handle_order'),
            'my-trades' => array($this, 'handle_my_trade'),
            'my-balance' => array($this, 'handle_balance'),
            'added-order' => array($this, 'handle_create_order'),
            'canceled-order' => array($this, 'handle_cancel_order'),
            'canceled-orders' => array($this, 'handle_cancel_orders'),
            'canceled-all-orders' => array($this, 'handle_cancel_all_orders'),
            'subscribe' => array($this, 'handle_subscription_status'),
            'unsubscribe' => array($this, 'handle_subscription_status'),
        );
        $method = $this->safe_value($methods, $event);
        if ($method !== null) {
            $method($client, $message);
        }
    }
}
